            println!("cargo:rustc-env=C_VERSION={C_VERSION}");
        } else {
            fs::write(out.join("bindings.rs"), bindings).unwrap();
            static_fns = out.join("static_fns.c");
            fs::write(&static_fns, fns.unwrap_or_default()).unwrap();
            println!("cargo:rustc-cfg=crustify_regenerated");
            println!("cargo:rustc-env=C_VERSION={}", lib.version);
        }
    } else {
        println!("cargo:rustc-env=C_VERSION={C_VERSION}");
    }
    compile_wrappers(&input, &lib, &static_fns);
}

/// The host's glibc: its headers are the compiler's default ones, and every Rust binary
/// links it already.
fn host_library() -> Library {
    let out = Command::new("getconf")
        .arg("GNU_LIBC_VERSION")
        .output()
        .expect("getconf GNU_LIBC_VERSION");
    let text = String::from_utf8(out.stdout).expect("getconf prints UTF-8");
    let version = text
        .trim()
        .strip_prefix("glibc ")
        .unwrap_or_else(|| panic!("getconf GNU_LIBC_VERSION printed {text:?}, not glibc's"))
        .to_string();
    Library {
        include: Vec::new(),
        version,
    }
}

/// Compiles the macro shims and the wrappers of the `static inline` functions.
fn compile_wrappers(input: &Path, lib: &Library, static_fns: &Path) {
    let mut cc = cc::Build::new();
    cc.file(input.join("shims.c"))
        .includes(&lib.include)
        .include(input)
        .warnings(false);
    if fs::metadata(static_fns).is_ok_and(|m| m.len() > 0) {
        cc.file(static_fns);
    }
    cc.compile(&format!("crustify_{LIB}_wrappers"));
}

/// Fails the build when `path` does not hold `content`, unless asked to write it; the
/// content generated is left in `out` for comparison.
fn check_or_update(path: &Path, content: &str, out: &Path) {
    if fs::read_to_string(path).unwrap_or_default() == content {
        return;
    }
    if env::var_os("CRUSTIFY_BINDINGS_UPDATE").is_some() {
        if content.is_empty() {
            let _ = fs::remove_file(path);
        } else {
            fs::write(path, content).unwrap();
        }
        return;
    }
    let generated = out.join(path.file_name().unwrap());
    fs::write(&generated, content).unwrap();
    panic!(
        "{} does not match its bindgen input, which generates {}: rebuild with \
         CRUSTIFY_BINDINGS_UPDATE=1 and commit it",
        path.display(),
        generated.display()
    );
}

//! Raw bindgen bindings to glibc's `libc`.
//!
//! Generated from the host's headers through `bindgen/wrapper.h` under
//! `bindgen/allowlist.txt`, and shipped as `src/bindings.rs`, which the `bindgen` feature
//! regenerates against the host's glibc.
#![allow(
    nonstandard_style,
    missing_docs,
    dead_code,
    unused_imports,
    clippy::all,
    clippy::pedantic
)]

#[cfg(not(all(target_arch = "x86_64", target_os = "linux", target_env = "gnu")))]
compile_error!(
    "libc-sys supports x86_64-unknown-linux-gnu only, the target its bindings are generated for"
);

/// The version of glibc the bindings were generated from, as `getconf GNU_LIBC_VERSION`
/// reports it.
pub const C_VERSION: &str = env!("C_VERSION");

#[cfg(not(crustify_regenerated))]
include!("bindings.rs");
#[cfg(crustify_regenerated)]
include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
[package]
name = "libc-sys"
description = "Raw FFI bindings to glibc, generated from the host's headers"
links = "c"
build = "build.rs"
version.workspace = true
edition.workspace = true
license.workspace = true
rust-version.workspace = true
repository.workspace = true
publish.workspace = true

[lib]
# C doc comments carry C code blocks that are not Rust doctests.
doctest = false

[build-dependencies]
# Pinned exactly: the committed bindings are its output.
bindgen = { workspace = true, optional = true }
cc.workspace = true

[features]
# Regenerates the bindings from the host's headers, in place of the shipped ones.
bindgen = ["dep:bindgen"]

